/// The wordmark's bounds in font units: x from the M's left edge to the t's
/// right edge, y from cap height down to the bottom of the y's loop.
fn bounds() -> (f32, f32, f32, f32) {
    let mut b = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    for c in WORDMARK {
        for &(x, y) in *c {
            b = (b.0.min(x), b.1.min(y), b.2.max(x), b.3.max(y));
        }
    }
    b
}

/// Even-odd coverage of `contours` on a `w`×`h` grid, 4×4 samples a pixel, where
/// a point in contour units lands at `p * scale + offset` in pixels. Scanline:
/// each sample row finds where the edges cross it and fills between pairs.
pub fn coverage(contours: &[&[(f32, f32)]], w: usize, h: usize, scale: f32, offset: Vec2) -> Vec<f32> {
    const SS: usize = 4;
    let mut out = vec![0.0f32; w * h];
    let mut xs: Vec<f32> = Vec::new();
    for py in 0..h {
        for sy in 0..SS {
            let gy = (py as f32 + (sy as f32 + 0.5) / SS as f32 - offset.y) / scale;
            xs.clear();
            for c in contours {
                let n = c.len();
                for i in 0..n {
                    let (a, b) = (c[i], c[(i + 1) % n]);
                    if (a.1 > gy) != (b.1 > gy) {
                        let gx = a.0 + (gy - a.1) * (b.0 - a.0) / (b.1 - a.1);
                        xs.push(gx * scale + offset.x);
                    }
                }
            }
            xs.sort_by(f32::total_cmp);
            for span in xs.chunks_exact(2) {
                // Sample columns whose centres fall inside [x0, x1).
                let first = ((span[0] * SS as f32) - 0.5).ceil().max(0.0) as usize;
                let last = ((span[1] * SS as f32) - 0.5).ceil().min((w * SS) as f32) as usize;
                for s in first..last {
                    out[py * w + s / SS] += 1.0 / (SS * SS) as f32;
                }
            }
        }
    }
    out
}

/// The wordmark, `height` points tall (cap height to the y's loop), in `color`.
/// Rasterised once per size and kept as a texture.
pub fn wordmark(ui: &mut egui::Ui, height: f32, color: Color32) -> egui::Response {
    let (x0, y0, x1, y1) = bounds();
    let size = Vec2::new((x1 - x0) / (y1 - y0) * height, height);
    let (rect, resp) = ui.allocate_exact_size(size, egui::Sense::hover());
    paint_wordmark(ui.painter(), rect, color);
    resp
}

pub fn paint_wordmark(p: &egui::Painter, rect: Rect, color: Color32) {
    let ppp = p.ctx().pixels_per_point();
    let (w, h) = ((rect.width() * ppp).ceil() as usize, (rect.height() * ppp).ceil() as usize);
    if w == 0 || h == 0 {
        return;
    }
    let id = egui::Id::new(("mybot-wordmark", w, h));
    let tex = p.ctx().data_mut(|d| d.get_temp::<TextureHandle>(id)).unwrap_or_else(|| {
        let (x0, y0, x1, _) = bounds();
        let scale = w as f32 / (x1 - x0);
        let cov = coverage(WORDMARK, w, h, scale, Vec2::new(-x0 * scale, -y0 * scale));
        let px: Vec<Color32> = cov.iter().map(|&a| Color32::from_white_alpha((a.clamp(0.0, 1.0) * 255.0).round() as u8)).collect();
        let t = p.ctx().load_texture("mybot-wordmark", ColorImage::new([w, h], px), TextureOptions::LINEAR);
        p.ctx().data_mut(|d| d.insert_temp(id, t.clone()));
        t
    });
    p.image(tex.id(), rect, Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), color);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wordmark_fills_its_letters_and_leaves_the_counters() {
        let (x0, y0, x1, y1) = bounds();
        assert!(x1 - x0 > 3000.0 && y1 - y0 > 1000.0, "{x0} {y0} {x1} {y1}");
        // At 1 unit per pixel: inside the M's left stem is ink; the middle
        // of the o (its counter) is not.
        let (w, h) = ((x1 - x0) as usize + 1, (y1 - y0) as usize + 1);
        let cov = coverage(WORDMARK, w, h, 1.0, Vec2::new(-x0, -y0));
        let at = |x: f32, y: f32| cov[((y - y0) as usize) * w + (x - x0) as usize];
        assert!(at(x0 + 40.0, -500.0) > 0.9, "M stem");
        assert!(at(x0 + 40.0, y1 - 5.0) < 0.1, "below the M is empty");
    }
}
